package dev.deltavisuals.render;

import dev.deltavisuals.util.ColorUtil;
import dev.deltavisuals.util.Hash;

/**
 * Custom sky: a sphere around the camera drawn through {@link Gfx}. Everything is generated by code
 * (vertex-colour gradients, animated value noise, quads); there are no texture files and no particles.
 *
 * Layers, in draw order (every switch of pipeline flushes the previous one, so this order is what you see):
 *  1. dome        - opaque gradient sphere with sun glow, noise clouds / nebula / haze baked into vertex colours
 *  2. additive    - stars (twinkling), sun or moon glow, aurora curtains
 *  3. black hole  - opaque dark disc, then additive photon ring, glow and accretion disk
 *
 * The dome sits at a radius larger than the terrain fog distance and is depth-tested, so terrain, entities and
 * everything already in the depth buffer correctly hide it.
 */
public final class SkyRenderer {
    private static final double TAU = Math.PI * 2, HALF_PI = Math.PI / 2;

    /** One preset: default palette and character. */
    public static final class Look {
        public final String name;
        public int top, mid, horizon, bottom, glow, cloudLight, cloudDark;
        /** Base cloud coverage 0..1 (0 = none). */
        public float cover, cloudAlpha = 0.9f;
        /** Noise frequency along the azimuth / the elevation. Big azimuth + small elevation = streaks fanning from the zenith. */
        public float streakAz = 3f, streakEl = 3f;
        public float swirl, thickDark, zenithMass;
        public float sunStrength, sunWide = 0.6f, sunTall = 0.2f;
        public boolean sunCore, moon, nebula, aurora, hole, fantasy;
        /** Star amount 0..1 of the star catalogue. */
        public float stars;
        /** Uses the colour settings of the menu instead of the palette below. */
        public boolean custom;
        public int customKind;               // 0 = normal custom, 1 = plain gradient, 2 = single colour
        public Look(String name) { this.name = name; }
    }

    /** Everything that can change per frame. Filled by the CustomSky module. */
    public static final class Params {
        public Look look;
        public int top, horizon, bottom, glowColor, cloudLight, cloudDark;
        public float intensity = 1f, brightness = 1f, opacity = 1f, gradPower = 1f, hueShift, glow = 1f;
        public float cloudAmount = 1f, cloudContrast = 1f, cloudScale = 1f, starDensity = 1f, holeSize = 1f;
        public boolean stars = true, sun = true;
        public double sunAz, sunEl, time, radius = 300;
        public int quality = 1;
    }

    // ------------------------------------------------------------------ palette (floats, resolved per frame)
    private static final float[] TOP = new float[3], MID = new float[3], HOR = new float[3], BOT = new float[3],
        GLO = new float[3], CLL = new float[3], CLD = new float[3];
    private static double effSunAz, effSunEl;

    private static void toF(int rgb, float hue, float[] o) {
        if (hue != 0f) {
            float[] hsv = ColorUtil.toHsv(rgb);
            float h = hsv[0] + hue / 360f;
            h -= (float) Math.floor(h);
            rgb = ColorUtil.hsv(h, hsv[1], hsv[2], 255);
        }
        o[0] = ColorUtil.red(rgb) / 255f; o[1] = ColorUtil.green(rgb) / 255f; o[2] = ColorUtil.blue(rgb) / 255f;
    }

    private static void prepare(Params p) {
        Look L = p.look;
        float h = p.hueShift;
        int top = L.custom ? p.top : L.top, hor = L.custom ? p.horizon : L.horizon, bot = L.custom ? p.bottom : L.bottom;
        int mid = L.custom ? ColorUtil.lerp(top, hor, 0.5f) : L.mid;
        if (L.custom && L.customKind == 2) { mid = top; hor = ColorUtil.lerp(top, 0xFFFFFFFF, 0.10f); bot = ColorUtil.lerp(top, 0xFF000000, 0.22f); }
        if (!L.custom && p.top != 0) { top = p.top; hor = p.horizon; bot = p.bottom; mid = ColorUtil.lerp(top, hor, 0.5f); }
        toF(top, h, TOP); toF(mid, h, MID); toF(hor, h, HOR); toF(bot, h, BOT);
        int glow = (L.custom || p.glowColor != 0) ? p.glowColor : L.glow;
        int cl = (L.custom || p.cloudLight != 0) ? p.cloudLight : L.cloudLight, cd = (L.custom || p.cloudDark != 0) ? p.cloudDark : L.cloudDark;
        toF(glow, h, GLO); toF(cl, h, CLL); toF(cd, h, CLD);
        if (L.moon) { effSunAz = p.sunAz + 3.0; effSunEl = 0.62; } else { effSunAz = p.sunAz; effSunEl = p.sunEl; }
    }

    // ------------------------------------------------------------------ noise
    private static float lat(int x, int y, int z) { return Hash.f(x * 73856093 ^ y * 19349663 ^ z * 83492791 ^ 0x5bd1e995); }

    static float n3(double x, double y, double z) {
        int xi = (int) Math.floor(x), yi = (int) Math.floor(y), zi = (int) Math.floor(z);
        float fx = (float) (x - xi), fy = (float) (y - yi), fz = (float) (z - zi);
        fx = fx * fx * (3f - 2f * fx); fy = fy * fy * (3f - 2f * fy); fz = fz * fz * (3f - 2f * fz);
        float a = lat(xi, yi, zi), b = lat(xi + 1, yi, zi), c = lat(xi, yi + 1, zi), d = lat(xi + 1, yi + 1, zi);
        float e = lat(xi, yi, zi + 1), f = lat(xi + 1, yi, zi + 1), g = lat(xi, yi + 1, zi + 1), h = lat(xi + 1, yi + 1, zi + 1);
        float x1 = a + (b - a) * fx, x2 = c + (d - c) * fx, x3 = e + (f - e) * fx, x4 = g + (h - g) * fx;
        float y1 = x1 + (x2 - x1) * fy, y2 = x3 + (x4 - x3) * fy;
        return y1 + (y2 - y1) * fz;
    }

    static float fbm(double x, double y, double z, int oct) {
        float sum = 0f, amp = 0.5f, tot = 0f;
        for (int i = 0; i < oct; i++) {
            sum += amp * n3(x, y, z);
            tot += amp;
            x = x * 2.03 + 17.1; y = y * 2.03 + 3.7; z = z * 2.03 + 9.2;
            amp *= 0.5f;
        }
        return sum / tot;
    }

    private static float sm(float a, float b, float x) {
        float t = Math.max(0f, Math.min(1f, (x - a) / (b - a)));
        return t * t * (3f - 2f * t);
    }
    private static float c01(float x) { return Math.max(0f, Math.min(1f, x)); }
    private static float mix(float a, float b, float t) { return a + (b - a) * t; }
    private static void mix3(float[] a, float[] b, float t, float[] o) {
        o[0] = a[0] + (b[0] - a[0]) * t; o[1] = a[1] + (b[1] - a[1]) * t; o[2] = a[2] + (b[2] - a[2]) * t;
    }
    private static double wrapPi(double a) { a %= TAU; if (a > Math.PI) a -= TAU; if (a < -Math.PI) a += TAU; return a; }

    // ------------------------------------------------------------------ dome grid
    private static final double[] ROW_DEG = {-22, -12, -5, 0, 1.5, 3, 5, 7.5, 10, 13, 16.5, 20, 25, 30, 36, 43, 51, 60, 70, 80, 90};
    private static final int NR = ROW_DEG.length;
    private static int cols = -1;
    private static float[] dX, dY, dZ, vr, vg, vb;
    private static double[] vAz, vEl;
    private static double lastCompute = -1e9;
    private static int lastSig;

    private static void buildGrid(int nc) {
        cols = nc;
        int n = NR * nc;
        dX = new float[n]; dY = new float[n]; dZ = new float[n]; vr = new float[n]; vg = new float[n]; vb = new float[n];
        vAz = new double[n]; vEl = new double[n];
        for (int i = 0; i < NR; i++) {
            double el = Math.toRadians(ROW_DEG[i]), ce = Math.cos(el), se = Math.sin(el);
            for (int j = 0; j < nc; j++) {
                double az = j / (double) nc * TAU - Math.PI;
                int k = i * nc + j;
                dX[k] = (float) (Math.sin(az) * ce); dY[k] = (float) se; dZ[k] = (float) (Math.cos(az) * ce);
                vAz[k] = az; vEl[k] = el;
            }
        }
        lastCompute = -1e9;
    }

    private static int signature(Params p) {
        int h = 17;
        h = h * 31 + System.identityHashCode(p.look);
        h = h * 31 + p.top; h = h * 31 + p.horizon; h = h * 31 + p.bottom; h = h * 31 + p.glowColor;
        h = h * 31 + p.cloudLight; h = h * 31 + p.cloudDark;
        float[] f = {p.intensity, p.brightness, p.gradPower, p.hueShift, p.glow, p.cloudAmount, p.cloudContrast, p.cloudScale, (float) p.sunAz, (float) p.sunEl};
        for (float x : f) h = h * 31 + Float.floatToIntBits(x);
        return h * 31 + (p.sun ? 1 : 0);
    }

    // ------------------------------------------------------------------ per-vertex colour
    private static final float[] TMP = new float[3];

    private static void shade(Params p, double az, double el, double x, double y, double z, double t, float[] o) {
        Look L = p.look;
        float e = (float) el;
        float r, g, b;
        // 1) vertical gradient: horizon -> middle -> zenith, and horizon -> bottom below the horizon
        if (e >= 0f) {
            float u = (float) Math.pow(e / HALF_PI, p.gradPower);
            if (u < 0.35f) { float k = u / 0.35f; k = 0.5f * k + 0.5f * k * k * (3f - 2f * k); mix3(HOR, MID, k, o); }
            else { float k = (u - 0.35f) / 0.65f; k = 0.5f * k + 0.5f * k * k * (3f - 2f * k); mix3(MID, TOP, k, o); }
        } else {
            float k = c01(-e / 0.38f); k = k * k * (3f - 2f * k);
            mix3(HOR, BOT, k, o);
        }

        float inten = p.intensity;
        double daz = wrapPi(az - effSunAz), del = el - effSunEl;
        float sunProx = (float) Math.exp(-(daz * daz) / (2 * 0.9 * 0.9));

        // 2) sun / moon glow: an anisotropic blob plus a wide soft halo
        if (L.sunStrength > 0f && p.sun) {
            double sw = L.sunWide, st = L.sunTall;
            float g1 = (float) Math.exp(-(daz * daz / (2 * sw * sw) + del * del / (2 * st * st)));
            float g2 = 0.22f * (float) Math.exp(-(daz * daz / (2 * sw * sw * 6.0) + del * del / (2 * st * st * 4.0)));
            float gl = (0.62f * g1 + g2) * L.sunStrength * p.glow * inten;
            // glow tints the sky (lerp towards the glow colour) instead of just adding light, so it never clips to white
            float gm = c01(gl);
            o[0] = mix(o[0], GLO[0], gm); o[1] = mix(o[1], GLO[1], gm); o[2] = mix(o[2], GLO[2], gm);
            float w = c01(g1 * g1 * g1 * 0.45f * L.sunStrength * p.glow * inten);
            o[0] = mix(o[0], 1f, w); o[1] = mix(o[1], 1f, w); o[2] = mix(o[2], 1f, w);
        }

        // 3) animated noise clouds (streaks fan out from the zenith, with a slow swirl)
        float cl = (L.cover + L.zenithMass * sm(0.30f, 1.3f, e)) * p.cloudAmount * (0.35f + 0.65f * inten);
        if (cl > 0.002f) {
            double rho = HALF_PI - el;
            double sr = Math.sin(Math.min(Math.max(rho, 0), Math.PI));
            double a2 = az + L.swirl * Math.pow(Math.max(0, el) / HALF_PI, 1.4) * 2.4 + t * 0.012 * (0.4 + 0.3 * L.swirl);
            double sc = p.cloudScale;
            double nx = Math.cos(a2) * sr * L.streakAz * sc, nz = Math.sin(a2) * sr * L.streakAz * sc;
            double ny = rho * L.streakEl * sc + t * 0.035;
            float w = n3(nx * 0.55 + 11.3, ny * 0.55, nz * 0.55 + t * 0.02);
            float f = fbm(nx + w * 0.8, ny + w * 0.5, nz, 4);
            float thr = 1f - cl;
            float width = 0.20f / Math.max(0.2f, p.cloudContrast);
            float m = sm(thr - width, thr + width, f);
            m *= (0.30f + 0.70f * sm(-0.06f, 0.25f, e)) * L.cloudAlpha;
            if (m > 0.002f) {
                float thick = c01((f - thr) / 0.22f + 0.15f);
                float dk = mix((1f - thick) * 0.55f, thick, L.thickDark);
                dk *= 1f - 0.55f * sunProx;
                mix3(CLL, CLD, c01(dk), TMP);
                float rim = sunProx * 0.30f * (1f - thick) * p.glow;
                TMP[0] += GLO[0] * rim; TMP[1] += GLO[1] * rim; TMP[2] += GLO[2] * rim;
                o[0] = mix(o[0], TMP[0], m); o[1] = mix(o[1], TMP[1], m); o[2] = mix(o[2], TMP[2], m);
            }
        }

        // 4) preset specific atmosphere
        if (L.nebula) {
            float n1 = fbm(x * 1.9 + 3.1, y * 1.9, z * 1.9 + t * 0.004, 5), n2 = fbm(x * 3.2 - 7.7, y * 3.2 + 1.3, z * 3.2 + t * 0.006, 4);
            double dn = x * 0.32 + y * 0.86 - z * 0.40;
            float band = (float) Math.exp(-(dn * dn) / (2 * 0.2 * 0.2));
            float a = sm(0.40f, 0.82f, n1) * inten;
            float bb = sm(0.44f, 0.86f, n2) * inten;
            float k1 = a * (0.30f + 0.55f * band) * p.glow, k2 = bb * (0.20f + 0.45f * band) * p.glow;
            o[0] += CLL[0] * k1 + CLD[0] * k2 + GLO[0] * band * 0.10f * inten * p.glow;
            o[1] += CLL[1] * k1 + CLD[1] * k2 + GLO[1] * band * 0.10f * inten * p.glow;
            o[2] += CLL[2] * k1 + CLD[2] * k2 + GLO[2] * band * 0.10f * inten * p.glow;
        }
        if (L.aurora) {
            float aur = sm(0.0f, 0.45f, e) * (1f - sm(0.9f, 1.45f, e));
            float f = fbm(x * 2.2, y * 2.2 + t * 0.02, z * 2.2, 4);
            float k = aur * f * f * 1.6f * inten * p.glow;
            o[0] += (0.10f * GLO[0] + 0.12f) * k * 0.6f; o[1] += GLO[1] * 0.22f * k; o[2] += (GLO[2] * 0.14f + 0.20f * f) * k;
        }
        if (L.hole) {
            double ang = Math.acos(Math.max(-1, Math.min(1, x * Math.sin(effSunAz) * Math.cos(holeEl()) + y * Math.sin(holeEl()) + z * Math.cos(effSunAz) * Math.cos(holeEl()))));
            float k = (float) Math.exp(-(ang * ang) / (2 * 0.5 * 0.5)) * 0.14f * p.glow * inten;
            o[0] += GLO[0] * k; o[1] += GLO[1] * k; o[2] += GLO[2] * k;
        }
        if (L.fantasy) {
            double a = az * 0.9 + t * 0.02;
            float k = 0.07f * sm(0.05f, 0.7f, e) * (1f - sm(0.9f, 1.5f, e)) * inten;
            o[0] += (0.5f + 0.5f * (float) Math.sin(a)) * k; o[1] += (0.5f + 0.5f * (float) Math.sin(a + 2.1)) * k; o[2] += (0.5f + 0.5f * (float) Math.sin(a + 4.2)) * k;
        }

        // brightness and a soft clamp so strong glow does not clip into flat white patches
        float br = p.brightness;
        for (int i = 0; i < 3; i++) {
            float v = o[i] * br;
            o[i] = v <= 0.8f ? Math.max(0f, v) : 0.8f + 0.2f * (1f - (float) Math.exp(-(v - 0.8f) * 5f));
        }
    }

    private static double holeEl() { return Math.max(effSunEl, 0.42); }

    // ------------------------------------------------------------------ stars
    private static final int NS = 1500;
    private static final float[] SX = new float[NS], SY = new float[NS], SZ = new float[NS], SM = new float[NS],
        SPH = new float[NS], SSP = new float[NS], SCOL = new float[NS];
    static {
        for (int i = 0; i < NS; i++) {
            float y = Hash.s(11, i);
            double az = Hash.f(12, i) * TAU, r = Math.sqrt(Math.max(0, 1 - y * y));
            SX[i] = (float) (r * Math.sin(az)); SY[i] = y; SZ[i] = (float) (r * Math.cos(az));
            SM[i] = (float) Math.pow(Hash.f(13, i), 3.2);
            SPH[i] = Hash.f(14, i) * (float) TAU;
            SSP[i] = 1.2f + Hash.f(15, i) * 3f;
            SCOL[i] = Hash.f(16, i);
        }
    }

    private static void drawStars(Params p, double R) {
        Look L = p.look;
        float amount = L.stars * p.starDensity;
        if (!p.stars || amount <= 0.001f) return;
        int n = Math.min(NS, (int) (NS * Math.min(1f, amount)));
        double Rs = R * 0.985, t = p.time;
        double cx = Gfx.camX, cy = Gfx.camY, cz = Gfx.camZ;
        for (int i = 0; i < n; i++) {
            if (SY[i] < -0.04f) continue;
            float m = SM[i];
            float tw = 0.62f + 0.38f * (float) Math.sin(t * SSP[i] + SPH[i]);
            float bright = c01((0.38f + 0.62f * m) * tw * p.intensity * (amount > 1f ? 1f + (amount - 1f) * 0.3f : 1f) * p.brightness);
            if (bright < 0.03f) continue;
            double x = cx + SX[i] * Rs, y = cy + SY[i] * Rs, z = cz + SZ[i] * Rs;
            double s = Rs * (0.0016 + 0.0042 * m) * (0.8 + 0.2 * tw);
            int rr = 255, gg = 255, bb = 255;
            if (SCOL[i] < 0.55f) { rr = 208; gg = 224; bb = 255; } else if (SCOL[i] > 0.86f) { rr = 255; gg = 226; bb = 186; }
            int c = ColorUtil.argb(Math.round(255 * bright), rr, gg, bb);
            diamond(x, y, z, s * 1.25, c);
            if (m > 0.70f && Gfx.hasBudget(40)) {
                int halo = ColorUtil.argb(Math.round(255 * bright * 0.42f), rr, gg, bb);
                halo(x, y, z, s * 6.5, halo);
                flare(x, y, z, s * 7.5, s * 0.30, SPH[i] * 0.2, ColorUtil.argb(Math.round(255 * bright * 0.8f), rr, gg, bb));
            }
        }
    }

    private static void diamond(double x, double y, double z, double s, int c) {
        Gfx.quad(x + Gfx.rightX * s, y + Gfx.rightY * s, z + Gfx.rightZ * s, c,
                 x + Gfx.upX * s, y + Gfx.upY * s, z + Gfx.upZ * s, c,
                 x - Gfx.rightX * s, y - Gfx.rightY * s, z - Gfx.rightZ * s, c,
                 x - Gfx.upX * s, y - Gfx.upY * s, z - Gfx.upZ * s, c);
    }

    /** Soft round glow facing the camera. argb alpha = peak. */
    private static void halo(double x, double y, double z, double radius, int argb) {
        int mid = ColorUtil.mulAlpha(argb, 0.40f), out = ColorUtil.withAlpha(argb, 0);
        Gfx.annulus(x, y, z, Gfx.rightX, Gfx.rightY, Gfx.rightZ, Gfx.upX, Gfx.upY, Gfx.upZ, 0, radius * 0.36, 0, TAU, 8, argb, mid);
        Gfx.annulus(x, y, z, Gfx.rightX, Gfx.rightY, Gfx.rightZ, Gfx.upX, Gfx.upY, Gfx.upZ, radius * 0.36, radius, 0, TAU, 8, mid, out);
    }

    private static void flare(double x, double y, double z, double length, double halfW, double rot, int argb) {
        int tip = ColorUtil.withAlpha(argb, 0);
        for (int k = 0; k < 4; k++) {
            double a = rot + k * Math.PI / 2, ca = Math.cos(a), sa = Math.sin(a);
            double dx = Gfx.rightX * ca + Gfx.upX * sa, dy = Gfx.rightY * ca + Gfx.upY * sa, dz = Gfx.rightZ * ca + Gfx.upZ * sa;
            double px = -Gfx.rightX * sa + Gfx.upX * ca, py = -Gfx.rightY * sa + Gfx.upY * ca, pz = -Gfx.rightZ * sa + Gfx.upZ * ca;
            double len = length * (k % 2 == 0 ? 1.0 : 0.6);
            Gfx.quad(x - px * halfW, y - py * halfW, z - pz * halfW, argb, x + px * halfW, y + py * halfW, z + pz * halfW, argb,
                     x + dx * len, y + dy * len, z + dz * len, tip, x + dx * len, y + dy * len, z + dz * len, tip);
        }
    }

    // ------------------------------------------------------------------ sun / moon disc glow
    private static final double[] BU = new double[3], BV = new double[3];

    private static void basis(double dx, double dy, double dz) {
        double ux, uy, uz;
        if (Math.abs(dy) > 0.98) { ux = 1; uy = 0; uz = 0; } else { ux = dz; uy = 0; uz = -dx; }   // up x d
        double l = Math.sqrt(ux * ux + uy * uy + uz * uz);
        ux /= l; uy /= l; uz /= l;
        BU[0] = ux; BU[1] = uy; BU[2] = uz;
        BV[0] = dy * uz - dz * uy; BV[1] = dz * ux - dx * uz; BV[2] = dx * uy - dy * ux;      // d x u
    }

    private static void drawSunDisc(Params p, double R) {
        Look L = p.look;
        if (!p.sun || L.sunStrength <= 0f || !(L.sunCore || L.moon)) return;
        double ce = Math.cos(effSunEl);
        double dx = Math.sin(effSunAz) * ce, dy = Math.sin(effSunEl), dz = Math.cos(effSunAz) * ce;
        double Rr = R * 0.975;
        double cx = Gfx.camX + dx * Rr, cy = Gfx.camY + dy * Rr, cz = Gfx.camZ + dz * Rr;
        basis(dx, dy, dz);
        float k = c01(p.glow * p.intensity * p.brightness);
        int white = L.moon ? ColorUtil.argb(255, 232, 240, 255) : ColorUtil.argb(255, 255, 250, 235);
        int glow = ColorUtil.argb(255, Math.round(GLO[0] * 255), Math.round(GLO[1] * 255), Math.round(GLO[2] * 255));
        double core = Rr * (L.moon ? 0.032 : 0.020), halo = Rr * (L.moon ? 0.20 : 0.26);
        Gfx.annulus(cx, cy, cz, BU[0], BU[1], BU[2], BV[0], BV[1], BV[2], 0, core, 0, TAU, 24, ColorUtil.mulAlpha(white, k), ColorUtil.mulAlpha(white, k * 0.95f));
        Gfx.annulus(cx, cy, cz, BU[0], BU[1], BU[2], BV[0], BV[1], BV[2], core, core * 3.0, 0, TAU, 24, ColorUtil.mulAlpha(glow, k * 0.60f), ColorUtil.mulAlpha(glow, k * 0.16f));
        Gfx.annulus(cx, cy, cz, BU[0], BU[1], BU[2], BV[0], BV[1], BV[2], core * 3.0, halo, 0, TAU, 24, ColorUtil.mulAlpha(glow, k * 0.16f), ColorUtil.withAlpha(glow, 0));
    }

    // ------------------------------------------------------------------ aurora curtains
    private static final int AN = 200, AK = 8;
    private static final double[] AX = new double[(AN + 1) * (AK + 1)], AY = new double[(AN + 1) * (AK + 1)], AZ = new double[(AN + 1) * (AK + 1)];
    private static final int[] AC = new int[(AN + 1) * (AK + 1)];

    private static void drawAurora(Params p, double R) {
        double t = p.time, Ra = R * 0.97, cx = Gfx.camX, cy = Gfx.camY, cz = Gfx.camZ;
        float k = p.intensity * p.glow * p.brightness;
        for (int c = 0; c < 3; c++) {
            double baseAz = c * 2.3 + 0.5 + t * 0.006 * (c + 1);
            for (int i = 0; i <= AN; i++) {
                double s = i / (double) AN;
                double az = baseAz + (s - 0.5) * 2.7 + 0.28 * Math.sin(s * 4.6 + t * 0.11 + c * 1.7) + 0.12 * Math.sin(s * 11 + t * 0.2 + c);
                double e0 = 0.09 + 0.05 * c + 0.06 * Math.sin(s * 6.2 + t * 0.13 + c);
                double h = 0.36 + 0.22 * n3(s * 3.1 + c * 7, t * 0.05, 1.7);
                float env = sm(0f, 0.14f, (float) s) * sm(1f, 0.86f, (float) s);
                float ray = 0.28f + 0.72f * n3(s * 60 + c * 13, t * 0.35, 3.3);
                float bright = env * ray * (0.55f + 0.45f * n3(s * 5 + c * 3, t * 0.08, 5.1));
                for (int j = 0; j <= AK; j++) {
                    float v = j / (float) AK;
                    double el = e0 + v * h, ce = Math.cos(el);
                    int idx = i * (AK + 1) + j;
                    AX[idx] = cx + Math.sin(az) * ce * Ra; AY[idx] = cy + Math.sin(el) * Ra; AZ[idx] = cz + Math.cos(az) * ce * Ra;
                    float prof = sm(0f, 0.12f, v) * (float) Math.pow(1f - v, 1.5);
                    float r, g, b;
                    if (v < 0.45f) { float q = v / 0.45f; r = mix(0.17f, 0.18f, q); g = mix(1.0f, 0.91f, q); b = mix(0.54f, 0.82f, q); }
                    else { float q = (v - 0.45f) / 0.55f; r = mix(0.18f, 0.60f, q); g = mix(0.91f, 0.36f, q); b = mix(0.82f, 1.0f, q); }
                    float a = c01(bright * prof * 0.95f * k);
                    AC[idx] = ColorUtil.argb(Math.round(a * 255), Math.round(r * 255), Math.round(g * 255), Math.round(b * 255));
                }
            }
            if (!Gfx.hasBudget(AN * AK)) return;
            for (int i = 0; i < AN; i++) {
                for (int j = 0; j < AK; j++) {
                    int a = i * (AK + 1) + j, b = (i + 1) * (AK + 1) + j, c1 = b + 1, d = a + 1;
                    if (((AC[a] | AC[b] | AC[c1] | AC[d]) >>> 24) == 0) continue;
                    Gfx.quad(AX[a], AY[a], AZ[a], AC[a], AX[b], AY[b], AZ[b], AC[b], AX[c1], AY[c1], AZ[c1], AC[c1], AX[d], AY[d], AZ[d], AC[d]);
                }
            }
        }
    }

    // ------------------------------------------------------------------ black hole
    private static void holeSetup(double[] out, double R) {
        double el = holeEl(), ce = Math.cos(el);
        double dx = Math.sin(effSunAz) * ce, dy = Math.sin(el), dz = Math.cos(effSunAz) * ce;
        out[0] = dx; out[1] = dy; out[2] = dz;
    }

    private static final double[] HD = new double[3];

    private static void drawHoleDisc(Params p, double R) {
        holeSetup(HD, R);
        double Rh = R * 0.96, r0 = Rh * 0.15 * p.holeSize;
        double cx = Gfx.camX + HD[0] * Rh, cy = Gfx.camY + HD[1] * Rh, cz = Gfx.camZ + HD[2] * Rh;
        basis(HD[0], HD[1], HD[2]);
        int black = ColorUtil.argb(255, 0, 0, 0);
        Gfx.annulus(cx, cy, cz, BU[0], BU[1], BU[2], BV[0], BV[1], BV[2], 0, r0 * 1.02, 0, TAU, 40, black, black);
    }

    private static void drawHoleGlow(Params p, double R) {
        holeSetup(HD, R);
        double t = p.time, Rh = R * 0.96, r0 = Rh * 0.15 * p.holeSize;
        double cx = Gfx.camX + HD[0] * Rh, cy = Gfx.camY + HD[1] * Rh, cz = Gfx.camZ + HD[2] * Rh;
        basis(HD[0], HD[1], HD[2]);
        double ux = BU[0], uy = BU[1], uz = BU[2], vx = BV[0], vy = BV[1], vz = BV[2];
        float k = c01(p.intensity * p.glow * p.brightness);
        int hotWhite = ColorUtil.argb(255, 255, 250, 240);
        // glow around the hole
        Gfx.annulus(cx, cy, cz, ux, uy, uz, vx, vy, vz, r0 * 0.98, r0 * 1.14, 0, TAU, 56, ColorUtil.mulAlpha(hotWhite, k), ColorUtil.argb(Math.round(140 * k), 255, 214, 160));
        Gfx.annulus(cx, cy, cz, ux, uy, uz, vx, vy, vz, r0 * 1.14, r0 * 1.7, 0, TAU, 56, ColorUtil.argb(Math.round(140 * k), 255, 214, 160), ColorUtil.argb(Math.round(80 * k), 255, 150, 70));
        Gfx.annulus(cx, cy, cz, ux, uy, uz, vx, vy, vz, r0 * 1.7, r0 * 4.2, 0, TAU, 56, ColorUtil.argb(Math.round(80 * k), 255, 150, 70), ColorUtil.argb(0, 255, 120, 50));
        // lensed lower arc
        Gfx.annulus(cx - vx * r0 * 0.10, cy - vy * r0 * 0.10, cz - vz * r0 * 0.10, ux, uy, uz, vx, vy, vz, r0 * 1.0, r0 * 1.32, Math.PI * 1.05, Math.PI * 0.9, 30,
            ColorUtil.argb(Math.round(190 * k), 255, 236, 205), ColorUtil.argb(0, 255, 170, 90));
        // accretion disk: a thin band across the hole, brighter on the approaching (left) side
        double tilt = 0.07, ct = Math.cos(tilt), st = Math.sin(tilt);
        double ax = ux * ct + vx * st, ay = uy * ct + vy * st, az = uz * ct + vz * st;
        double bx = -ux * st + vx * ct, by = -uy * st + vy * ct, bz = -uz * st + vz * ct;
        final int N = 56;
        double span = r0 * 7.0;
        for (int pass = 0; pass < 2; pass++) {
            double thickMul = pass == 0 ? 1.0 : 3.4;
            float aMul = pass == 0 ? 1f : 0.22f;
            for (int i = 0; i < N; i++) {
                double x0 = -span + 2 * span * i / N, x1 = -span + 2 * span * (i + 1) / N;
                int[] cl = new int[2];
                double[] hh = new double[2], xs = {x0, x1};
                for (int q = 0; q < 2; q++) {
                    double u = Math.abs(xs[q]) / span;
                    double heat = 1.0 - u;
                    double dopp = Math.max(0.35, Math.min(1.25, 0.70 - 0.55 * (xs[q] / span)));
                    hh[q] = r0 * (0.06 + 0.15 * heat * heat) * thickMul;
                    float a = (float) Math.min(1.0, 0.95 * Math.pow(heat, 0.6) * dopp * (0.88 + 0.12 * Math.sin(t * 0.9 + xs[q] / r0 * 2.3))) * aMul * k;
                    int rr = 255, gg = (int) (150 + 86 * Math.pow(heat, 2)), bb = (int) (70 + 130 * Math.pow(heat, 3));
                    cl[q] = ColorUtil.argb(Math.round(a * 255), rr, Math.min(255, gg), Math.min(255, bb));
                }
                int e0 = ColorUtil.withAlpha(cl[0], 0), e1 = ColorUtil.withAlpha(cl[1], 0);
                Gfx.quad(cx + ax * x0 + bx * hh[0], cy + ay * x0 + by * hh[0], cz + az * x0 + bz * hh[0], e0,
                         cx + ax * x1 + bx * hh[1], cy + ay * x1 + by * hh[1], cz + az * x1 + bz * hh[1], e1,
                         cx + ax * x1, cy + ay * x1, cz + az * x1, cl[1],
                         cx + ax * x0, cy + ay * x0, cz + az * x0, cl[0]);
                Gfx.quad(cx + ax * x0, cy + ay * x0, cz + az * x0, cl[0],
                         cx + ax * x1, cy + ay * x1, cz + az * x1, cl[1],
                         cx + ax * x1 - bx * hh[1], cy + ay * x1 - by * hh[1], cz + az * x1 - bz * hh[1], e1,
                         cx + ax * x0 - bx * hh[0], cy + ay * x0 - by * hh[0], cz + az * x0 - bz * hh[0], e0);
            }
        }
    }

    // ------------------------------------------------------------------ main entry
    public static void draw(Params p) {
        if (p == null || p.look == null) return;
        Look L = p.look;
        prepare(p);
        int nc = p.quality <= 0 ? 80 : p.quality == 1 ? 144 : 224;
        if (nc != cols) buildGrid(nc);
        double t = p.time;
        int sig = signature(p);
        if (sig != lastSig || t < lastCompute || t - lastCompute > 1.0 / 30.0) {
            lastSig = sig; lastCompute = t;
            float[] o = new float[3];
            for (int k = 0; k < NR * nc; k++) {
                shade(p, vAz[k], vEl[k], dX[k], dY[k], dZ[k], t, o);
                vr[k] = o[0]; vg[k] = o[1]; vb[k] = o[2];
            }
        }
        double R = p.radius;
        double cx = Gfx.camX, cy = Gfx.camY, cz = Gfx.camZ;
        int alpha = Math.round(255 * Math.max(0f, Math.min(1f, p.opacity)));
        if (!Gfx.hasBudget(NR * nc + 400)) return;

        // 1) dome
        Gfx.use(false, false);
        for (int i = 0; i < NR - 1; i++) {
            for (int j = 0; j < nc; j++) {
                int j2 = (j + 1) % nc;
                int a = i * nc + j, b = i * nc + j2, c = (i + 1) * nc + j2, d = (i + 1) * nc + j;
                Gfx.quad(cx + dX[a] * R, cy + dY[a] * R, cz + dZ[a] * R, col(alpha, a),
                         cx + dX[b] * R, cy + dY[b] * R, cz + dZ[b] * R, col(alpha, b),
                         cx + dX[c] * R, cy + dY[c] * R, cz + dZ[c] * R, col(alpha, c),
                         cx + dX[d] * R, cy + dY[d] * R, cz + dZ[d] * R, col(alpha, d));
            }
        }

        // 2) additive layer: stars, sun / moon, aurora
        boolean extras = (L.stars > 0f && p.stars) || (L.sunStrength > 0f && (L.sunCore || L.moon)) || L.aurora || L.hole;
        if (!extras) return;
        Gfx.use(true, false);
        drawStars(p, R);
        drawSunDisc(p, R);
        if (L.aurora) drawAurora(p, R);

        // 3) black hole: opaque dark disc (alpha pipeline) then additive glow and disk
        if (L.hole) {
            Gfx.use(false, false);
            drawHoleDisc(p, R);
            Gfx.use(true, false);
            drawHoleGlow(p, R);
        }
    }

    private static int col(int a, int k) {
        return ColorUtil.argb(a, Math.round(vr[k] * 255f), Math.round(vg[k] * 255f), Math.round(vb[k] * 255f));
    }
}
